import{_ as o,o as a,c as t,ah as n}from"./chunks/framework.BsNNkeaH.js";const p=JSON.parse('{"title":"Your student space","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/eleve/index.md","filePath":"src/en/guide/eleve/index.md"}'),r={name:"en/guide/eleve/index.md"};function s(i,e,d,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="your-student-space" tabindex="-1">Your student space <a class="header-anchor" href="#your-student-space" aria-label="Permalink to &quot;Your student space&quot;">​</a></h1><p>As a student, you have your own dashboard in ERA to follow your grades, classes and documents. This guide covers everything you can view and download there.</p><h2 id="your-dashboard" tabindex="-1">Your dashboard <a class="header-anchor" href="#your-dashboard" aria-label="Permalink to &quot;Your dashboard&quot;">​</a></h2><p>Once signed in, you land on the <strong>My portal</strong> page, showing your name, class and site. If you have no current enrollment, a message tells you so and the rest of the sections don&#39;t display.</p><h2 id="your-grades" tabindex="-1">Your grades <a class="header-anchor" href="#your-grades" aria-label="Permalink to &quot;Your grades&quot;">​</a></h2><p>The <strong>Grades</strong> section lists your per-subject averages, period by period, with your annual average shown at the top of the section.</p><h2 id="downloading-your-report-cards" tabindex="-1">Downloading your report cards <a class="header-anchor" href="#downloading-your-report-cards" aria-label="Permalink to &quot;Downloading your report cards&quot;">​</a></h2><p>The <strong>Report cards</strong> section lists your published report cards, period by period. Click <strong>Download</strong> next to a period to get your report card as a PDF. A report card only appears here once the school has published it.</p><h2 id="lesson-log" tabindex="-1">Lesson log <a class="header-anchor" href="#lesson-log" aria-label="Permalink to &quot;Lesson log&quot;">​</a></h2><p>The <strong>Lesson log</strong> section lists the lessons given, with date, subject, content and homework assigned. When a lesson has an attached document, an <strong>Attachment</strong> link appears next to that row — click it to open it.</p><h2 id="timetable" tabindex="-1">Timetable <a class="header-anchor" href="#timetable" aria-label="Permalink to &quot;Timetable&quot;">​</a></h2><p>The <strong>Timetable</strong> section shows your weekly schedule (day, start time, end time, subject). To import it into your own calendar (Google Calendar, Apple Calendar, Outlook…):</p><ol><li>Click <strong>Export to calendar</strong>.</li><li>An <code>.ics</code> file is downloaded; open it or import it into your usual calendar app.</li></ol><h2 id="boarding" tabindex="-1">Boarding <a class="header-anchor" href="#boarding" aria-label="Permalink to &quot;Boarding&quot;">​</a></h2><p>If you board at the school, a <strong>Boarding</strong> section shows your site, room and bed, along with your boarding attendance.</p><h2 id="attendance-and-discipline" tabindex="-1">Attendance and discipline <a class="header-anchor" href="#attendance-and-discipline" aria-label="Permalink to &quot;Attendance and discipline&quot;">​</a></h2><p>The <strong>Attendance</strong> section shows each day with its status (Present, Absent, Late) and the justification note if there is one. Justifying an absence is done by your parent or guardian from the parent portal — you cannot do it yourself from your space.</p><p>The <strong>Disciplinary incidents</strong> section lists incidents concerning you (date, severity, description, sanction), and <strong>Disciplinary councils</strong> those held for you, with their decision.</p>',18)])])}const g=o(r,[["render",s]]);export{p as __pageData,g as default};
